//! Test adapter only: explicit UTF-8 inputs in, generated bytes out. Not rpp CLI.
#[path = "../src/lex/mod.rs"]
#[allow(dead_code)]
mod lex;
#[path = "../src/preprocess/mod.rs"]
#[allow(dead_code)]
mod preprocess;

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let edition = match args[0].as_str() {
        "2021" => lex::Edition::Rust2021,
        "2024" => lex::Edition::Rust2024,
        _ => panic!("test edition"),
    };
    let mut sources = preprocess::Sources::default();
    for path in &args[2..] {
        sources
            .insert(path, std::fs::read_to_string(path).unwrap())
            .unwrap();
    }
    let options = preprocess::Options {
        edition,
        include_dirs: vec!["search directory".into()],
        definitions: vec![
            preprocess::InitialDefinition::Define("CONFIG".into(), "2".into()),
            preprocess::InitialDefinition::Undef("CONFIG".into()),
            preprocess::InitialDefinition::Define("CONFIG".into(), "1".into()),
        ],
    };
    match preprocess::preprocess(&sources, &args[1], &options) {
        Ok(output) => {
            let mut end = 0;
            for mapping in &output.mappings {
                assert_eq!(mapping.generated.start, end);
                end = mapping.generated.end;
                assert!(output.text.is_char_boundary(end));
            }
            assert_eq!(end, output.text.len());
            eprintln!("dependencies: {:?}", output.dependencies);
            eprintln!("mappings: {:?}", output.mappings);
            print!("{}", output.text);
        }
        Err(error) => {
            eprintln!("{error}");
            std::process::exit(1);
        }
    }
}
